try:
    print('>>> f = hasattr')
    print('>>> x = 1j')
    print('>>> y = slice(0)')
    print('>>> f(x, y)')
    f = hasattr
    x = 1j
    y = slice(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
